'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let me=null,config={},route={},generation=0,stream=null,scanStop=null;
const state={};
const icons={home:'M3 11 12 3l9 8v10h-6v-7H9v7H3z',shelf:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',lists:'M8 5h13 M8 12h13 M8 19h13 M3 5h.1 M3 12h.1 M3 19h.1',plus:'M12 3v18 M3 12h18',profile:'M20 21v-3a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v3 M16 5a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10 M9 22h6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',comment:'M21 15a4 4 0 0 1-4 4H7l-4 3V6a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z',eye:'M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.lists}"/></svg>`;
const logo='<span class="brand">B<span>OO</span>KCLUB</span>';
const statuses={'lendo':'Lendo','quero-ler':'Quero ler','lido':'Lidos','pausado':'Pausados','abandonado':'Abandonados'};
const field=(label,name,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label>${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const select=(label,name,options,value)=>`<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const check=(label,name,value=false)=>`<label class="inline"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const btn=(label,action,id='',cls='btn')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const head=(title,sub)=>!title?'':`<header class="pagehead"><h1>${esc(title)}</h1>${sub?`<p class="tagline">${esc(sub)}</p>`:''}</header>`;
const empty=(message,link='')=>`<div class="empty">${esc(message)}${link}</div>`;
function safeURL(value,image=false){if(image&&/^data:image\/(png|jpeg|webp);base64,/.test(value||''))return value;try{const u=new URL(value);if(u.protocol==='https:')return u.href;}catch{}return '';}
function fallbackCover(b){return `<span class="cover cover-fallback" role="img" aria-label="Capa oficial indisponível: ${esc(b.title||'Livro')}"><strong>${esc(b.title||'Livro')}</strong><small>${esc(b.author||'')}</small><em>Capa indisponível</em></span>`;}
function cover(b){const url=safeURL(b.cover_url,true);return url?`<img class="cover" src="${esc(url)}" data-book-title="${esc(b.title||'Livro')}" data-book-author="${esc(b.author||'')}" alt="Capa de ${esc(b.title)}" loading="lazy">`:fallbackCover(b);}
function avatar(u){const url=safeURL(u.avatar,true);return url?`<img class="avatar" src="${esc(url)}" alt="Avatar de ${esc(u.name)}">`:`<span class="avatar" aria-hidden="true">${esc((u.name||'L').slice(0,1))}</span>`;}
const person=u=>`<a class="person" href="#profile?id=${u.user_id||u.id}">${avatar(u)}<span><strong>${esc(u.name)}</strong><small>@${esc(u.username)}</small></span></a>`;
const star=n=>`<span class="stars" aria-label="${Number(n)||0} de 5 estrelas">${'★'.repeat(Math.floor(Number(n)||0))}${Number(n)%1?'½':''}<small> ${Number(n)||'Sem nota'}</small></span>`;
const date=v=>v?new Date(v).toLocaleDateString('pt-BR',{timeZone:'UTC'}):'—';
const iso=v=>v?new Date(v).toISOString().slice(0,10):'';
const bookCard=b=>`<a class="book" href="#book?id=${b.book_id||b.id}">${cover(b)}<strong>${esc(b.title)}</strong><small>${esc(b.author)}</small>${b.status?`<small class="status">${statuses[b.status]}${b.status==='lendo'?' · '+b.progress+'%':''}</small>`:''}</a>`;
const books=items=>items.length?`<div class="grid">${items.map(bookCard).join('')}</div>`:empty('Sua próxima leitura pode começar por uma busca.','<a href="#search">Explorar livros</a>');
const link=(r,title,ico)=>`<a class="navlink ${route.name===r?'active':''}" href="#${r}">${icon(ico||r)}<span>${title}</span></a>`;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(state.toast);state.toast=setTimeout(()=>$('#toast').style.display='none',4500);}
async function api(path,options={}){const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-BookClub-Client':'web',...options.headers}});let data;try{data=await response.json();}catch{throw Error('Resposta inválida do servidor.');}if(!response.ok){if(response.status===401&&!path.startsWith('/auth/')){me=null;location.hash='login';}throw Error(data.error||'Não foi possível concluir a operação.');}return data;}
const send=(path,body={},method='POST')=>api(path,{method,body:JSON.stringify(body)});
function parseRoute(){const [name,params='']=location.hash.slice(1).split('?');return {name:name||'home',params:new URLSearchParams(params)};}
function shell(content){return `<aside class="sidebar"><a href="#home">${logo}</a><p class="tagline">leituras que puxam conversa</p>${link('home','Início')}${link('shelf','Estante')}${link('lists','Listas')}${link('search','Busca')}${link('reviews','Resenhas','comment')}${link('profile','Perfil')}${link('goals','Metas','lists')}${link('stats','Estatísticas','lists')}<div class="bottom"><a class="btn primary" href="#create">${icon('plus')} Novo registro</a><p>${btn('Sair da conta','logout','','textbtn')}</p></div></aside><div class="shell"><div class="topbar"><a href="#profile" class="iconbtn" aria-label="Meu perfil">${icon('profile')}</a><a href="#home">${logo}<p class="tagline">leituras que puxam conversa</p></a><a href="#notifications" class="iconbtn" aria-label="Notificações">${icon('bell')}<span id="unread-dot" class="dot hidden"></span></a></div><main id="content" tabindex="-1">${content}</main></div><nav class="mobile-nav" aria-label="Navegação principal">${link('home','Início')}${link('shelf','Estante')}<a class="create" href="#create" aria-label="Novo registro">${icon('plus')}</a>${link('lists','Listas')}${link('search','Busca')}</nav>`;}
function mount(html){document.body.dataset.page=route.name||'home';$('#app').innerHTML=me?shell(html):html;$('#content')?.focus({preventScroll:true});wireImages();if(me&&route.name==='home')loadDiscovery();}
function wireImages(){document.querySelectorAll('img:not([data-image-wired])').forEach(img=>{img.dataset.imageWired='true';const fail=()=>{if(img.classList.contains('cover')){const holder=document.createElement('div');holder.innerHTML=fallbackCover({title:img.dataset.bookTitle||img.alt.replace(/^Capa de /,''),author:img.dataset.bookAuthor});img.replaceWith(holder.firstElementChild);}else{const placeholder=document.createElement('span');placeholder.className=img.className+' image-unavailable';placeholder.textContent=img.classList.contains('avatar')?'B':'Imagem indisponível';img.replaceWith(placeholder);}};img.addEventListener('error',fail,{once:true});if(img.complete&&!img.naturalWidth)fail();});}
function dialog(html){stopScan();$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();wireImages();}
function closeDialog(){stopScan();$('#modal').close();}
function stopScan(){if(scanStop){scanStop();scanStop=null;}}
$('#modal .close').addEventListener('click',closeDialog);$('#modal').addEventListener('close',stopScan);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function form(selector,handler){const el=$(selector);if(!el)return;el.addEventListener('submit',async e=>{e.preventDefault();const error=el.querySelector('.error');if(error)error.textContent='';const button=el.querySelector('[type=submit]');if(button?.disabled)return;if(button)button.disabled=true;try{await handler(Object.fromEntries(new FormData(el)),el);}catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{if(button)button.disabled=false;}});}
const submit=(text='Salvar')=>`<p class="error" role="alert"></p><button class="btn primary" type="submit">${text}</button>`;
const googleIcon='<svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#4285F4" d="M43.6 24.5c0-1.4-.1-2.7-.4-4.1H24v7.8h11a9.4 9.4 0 0 1-4.1 6.2v5h6.6c3.9-3.6 6.1-8.8 6.1-14.9z"/><path fill="#34A853" d="M24 44c5.5 0 10.1-1.8 13.5-4.9l-6.6-5a12.3 12.3 0 0 1-18.2-6.4H6v5.2A20.4 20.4 0 0 0 24 44z"/><path fill="#FBBC05" d="M12.7 27.7a12.2 12.2 0 0 1 0-7.4v-5.2H6a20 20 0 0 0 0 17.8z"/><path fill="#EA4335" d="M24 12.1c3 0 5.7 1 7.8 3l5.8-5.8A19.5 19.5 0 0 0 24 4 20.4 20.4 0 0 0 6 15.1l6.7 5.2A12.2 12.2 0 0 1 24 12.1z"/></svg>';
function authPage(mode='login'){
 const reg=mode==='register',forgot=mode==='forgot',reset=mode==='reset';const title=reg?'Comece sua estante':forgot?'Recuperar acesso':reset?'Uma nova senha':'Bem-vindo de volta';
 mount(`<main class="auth"><div class="auth-inner"><a href="#login">${logo}</a><p class="tagline">leia, sinta, compartilhe</p><section class="panel"><h1>${title}</h1><p class="sub">${reg?'guarde leituras, resenhas e desejos em um só lugar':'sua próxima história está esperando'}</p><form id="auth-form" class="form">${reg?field('Nome','name','text','','required minlength="2" maxlength="120" autocomplete="name"'):''}${!reset?field(reg||forgot?'E-mail':'E-mail ou usuário',reg||forgot?'email':'identifier',reg||forgot?'email':'text','','required autocomplete="username"'):''}${reg?field('Usuário','username','text','','required pattern="[a-zA-Z0-9][a-zA-Z0-9_.-]{2,39}" minlength="3" maxlength="40"'):''}${!forgot?`<label>Senha<div class="password"><input name="password" type="password" required ${reg||reset?'minlength="10" autocomplete="new-password"':'autocomplete="current-password"'}><button type="button" class="iconbtn" data-action="password" aria-label="Mostrar senha">${icon('eye')}</button></div><small>${reg||reset?'Pelo menos 10 caracteres.':''}</small></label>`:''}${submit(reg?'CRIAR CONTA':forgot?'ENVIAR LINK':reset?'ATUALIZAR SENHA':'ENTRAR')}</form>${mode==='login'?'<p class="switch"><a href="#forgot">Esqueci minha senha</a></p>':''}<p class="switch">${reg?'Já tem uma conta? <a href="#login">Entrar</a>':'<a href="#register">Criar conta</a>'}${forgot||reset?' · <a href="#login">Voltar ao login</a>':''}</p>${(mode==='login'||reg)?`<div class="auth-divider">ou continue com</div><div class="social">${config.oauth?.google?`<a class="btn google-signin" href="/api/auth/oauth/google">${googleIcon} Continuar com Google</a>`:`<button class="btn google-signin" disabled aria-label="Google indisponível no momento">${googleIcon} Google · em breve</button>`}</div>`:''}${route.params.get('oauth_error')?`<p class="error" role="alert">${esc(route.params.get('oauth_error')==='cancelled'?'Entrada com Google cancelada. Você pode tentar novamente.':route.params.get('oauth_error'))}</p>`:''}</section><small class="app-build">BookClub · 2.6.0</small></div></main>`);
 form('#auth-form',async values=>{if(forgot){const r=await send('/auth/forgot',values);toast(r.message);return;}if(reset){await send('/auth/reset',{...values,token:route.params.get('token')});toast('Senha atualizada. Entre novamente.');location.hash='login';return;}const r=await send('/auth/'+(reg?'register':'login'),values);me=r.user;connectStream();location.hash='home';if(reg)toast(r.emailSent?'Sua estante está pronta! Confira seu e-mail.':'Sua estante está pronta. Boas leituras!');else toast('Bem-vinda de volta, '+me.name.split(' ')[0]+'!');});
}
function reviewCard(r){return `<article class="review" id="review-${r.id}"><div class="row spread">${person(r)}<small>${date(r.created_at)}</small></div><a href="#book?id=${r.book_id}" class="review-book">${cover(r)}<span><h3>${esc(r.title)}</h3><small>${esc(r.author)}</small><p>${star(r.rating)}</p></span></a>${r.spoiler?`<details><summary>Esta resenha contém spoilers. Revelar conteúdo</summary><p class="review-text">${esc(r.content)}</p></details>`:`<p class="review-text">${esc(r.content)}</p>`}<div class="review-actions">${btn(icon('heart')+' '+r.likes,'like-review',r.id,'textbtn '+(r.liked?'liked':''))}${btn(icon('comment')+' '+r.comments,'comments',r.id,'textbtn')}${String(r.user_id)===String(me.id)?btn('Editar','edit-review',r.id,'textbtn')+btn('Excluir','delete-review',r.id,'textbtn'):''}</div></article>`;}
function sectionTitle(title,subtitle,href){return `<div class="home-section-heading"><div><h2>${esc(title)}</h2>${subtitle?`<p class="muted">${esc(subtitle)}</p>`:''}</div>${href?`<a href="${href}">Ver todos <span aria-hidden="true">↗</span></a>`:''}</div>`;}
function homeBooks(items){return `<div class="home-book-grid">${items.map(bookCard).join('')}</div>`;}
async function home(){const [collection,reviews,activities,suggestions]=await Promise.all([api('/home'),api('/reviews?following=true'),api('/activities'),api('/users/suggestions')]);state.reviews=reviews;
 return `<section class="reading-home"><div class="tabs home-tabs"><a class="selected" href="#home">Livros</a><a href="#reviews">Resenhas</a><a class="home-discover-link" href="#catalog">Descobrir ${icon('search')}</a></div><div id="daily-discovery" aria-live="polite"><div class="discovery-loading"><span class="eyebrow">Descoberta do dia</span><h2>Uma nova história está chegando.</h2><p class="muted">Preparando a leitura de hoje…</p></div></div>${sectionTitle('Bem avaliados no clube','As histórias que nossos leitores recomendam.','#search')}${collection.rated.length?homeBooks(collection.rated):`<div class="home-quiet"><span>${icon('comment')}</span><p>As primeiras resenhas vão revelar os favoritos do clube.<br><a href="#reviews">Compartilhe suas impressões</a></p></div>`}${sectionTitle('Novos no clube','Livros que acabaram de chegar à nossa estante.','#search')}${collection.latest.length?homeBooks(collection.latest):empty('Toda estante começa com uma história.','<a href="#catalog">Encontrar meu primeiro livro</a>')}<div class="home-community"><div>${sectionTitle('Leituras que puxam conversa','As últimas resenhas de quem você acompanha.','#reviews?following=true')}<div id="home-reviews">${reviews.slice(0,3).map(reviewCard).join('')||'<p class="muted">Siga leitores para descobrir novas perspectivas.</p>'}</div></div><aside class="home-readers">${sectionTitle('Encontre leitores','Sua próxima conversa pode começar por um livro.','')}${suggestions.map(u=>`<div class="activity">${person(u)}<small>${u.common_books} livro(s) em comum</small></div>`).join('')||'<p class="muted">Convide outras pessoas para o clube.</p>'}<details class="recent-activity"><summary>O que aconteceu no clube</summary><div id="home-activities">${activities.slice(0,6).map(a=>`<div class="activity"><a href="#profile?id=${a.user_id}">@${esc(a.username)}</a><p>${esc(a.content)}</p><small>${date(a.created_at)}</small></div>`).join('')||'<p class="muted">As movimentações da comunidade aparecerão aqui.</p>'}</div></details></aside></div></section>`;
}
function discoveryCard(d){if(!d.book)return `<section class="discovery-unavailable"><span class="eyebrow">Semana de ${esc(d.genre)}</span><h2>A próxima descoberta pode ser sua.</h2><p class="muted">A leitura de hoje ainda não está disponível. Explore o catálogo enquanto preparamos uma nova indicação.</p><a class="btn" href="#catalog">Descobrir livros ${icon('search')}</a></section>`;const b=d.book;return `<a class="daily-feature" href="${b.id?'#book?id='+b.id:'#discovery'}" aria-label="Conhecer ${esc(b.title)}"><div class="feature-accent" aria-hidden="true"></div><div class="feature-cover">${cover(b)}</div><div class="feature-copy"><span class="feature-kicker">DESCOBERTA DO DIA</span><span class="feature-theme">Semana de ${esc(d.genre)}</span><h1>${esc(b.title)}</h1><p class="feature-author">${esc(b.author)}</p><p class="feature-description">${esc(d.subtitle)}</p><span class="feature-cta">Conhecer a história <span aria-hidden="true">↗</span></span></div><span class="feature-daily-note">Um gênero por semana. Uma descoberta por dia.</span></a>`;}
async function loadDiscovery(){const current=generation;const holder=$('#daily-discovery');if(!holder)return;try{const d=await api('/discovery');if(current!==generation||route.name!=='home')return;state.discovery=d;holder.innerHTML=discoveryCard(d);wireImages();}catch{if(current===generation)holder.innerHTML=`<section class="discovery-unavailable"><span class="eyebrow">Descoberta do dia</span><h2>Uma pausa antes do próximo capítulo.</h2><p class="muted">Não foi possível carregar a indicação agora.</p>${btn('Tentar novamente','retry-discovery','','btn small')}</section>`;}}
async function discoveryPage(){const d=await api('/discovery');state.discovery=d;const b=d.book;if(!b)return head('Descoberta do dia','a próxima história está a caminho')+'<a href="#home">Voltar ao início</a>';if(b.id){location.hash='book?id='+b.id;return '';}return `<span class="eyebrow">Descoberta do dia · Semana de ${esc(d.genre)}</span><section class="detail discovery-detail">${cover(b)}<div><h1>${esc(b.title)}</h1><p class="muted">${esc(b.author)}</p><p>${esc(b.publisher||'')} ${esc(b.year||'')}</p><span class="badge">${esc(d.genre)}</span></div></section><div class="toolbar">${btn('Quero ler','save-discovery','','btn primary')}<a class="btn" href="#home">Voltar ao início</a></div><h2>Sobre a obra</h2><p class="synopsis">${esc(b.synopsis||'Sinopse não fornecida pelo catálogo.')}</p><p class="muted catalog-caption">Metadados: ${esc(b.source||'catálogo externo')}. Confira a edição antes de registrar sua leitura.</p>`;}
async function reviewsPage(){const following=route.params.get('following')==='true';const items=await api('/reviews?following='+following);state.reviews=items;state.reviewOffset=0;return `${head('Resenhas','opiniões que continuam depois da última página')}<div class="chips"><a class="chip ${!following?'selected':''}" href="#reviews">Pra você</a><a class="chip ${following?'selected':''}" href="#reviews?following=true">Seguindo</a></div><div class="feed" id="feed">${items.map(reviewCard).join('')||empty('Nenhuma resenha por aqui ainda.')}</div>${items.length===30?btn('Carregar mais','more-reviews','','btn more'):''}`;}
async function searchPage(){const type=route.params.get('type')||'books',term=route.params.get('q')||'',genre=route.params.get('genre')||'';let results='';if(type==='users'&&term){results=(await api('/users/search?q='+encodeURIComponent(term))).map(u=>`<div class="list-row">${person(u)}</div>`).join('')||empty('Nenhum leitor encontrado.');}
 else if(type==='lists'){const l=await api('/lists');results=l.filter(x=>(x.name+' '+x.description).toLowerCase().includes(term.toLowerCase())).map(listRow).join('')||empty('Nenhuma lista encontrada.');}
 else if(type==='books'&&(term||genre)){results=books(await api('/books?q='+encodeURIComponent(term)+'&genre='+encodeURIComponent(genre)));}
 const genres=[['Fantasia','dragões, magia, jornadas'],['Terror','medo, suspense, escuro'],['Romance','afetos, drama, encontros'],['Ficção científica','futuro, espaço, ideias'],['Distopia','revoltas, governos, escolhas'],['Suspense','segredos, pistas, tensão'],...(config.genres||[]).filter(g=>!['Fantasia','Terror','Romance','Ficção científica','Distopia','Suspense'].includes(g)).map(g=>[g,'explore as histórias do clube'])];
 return `${head('Busca','encontre livros, pessoas e listas')}<form id="search-form" class="searchbar"><input name="q" type="search" aria-label="Buscar por título, autor, usuário ou lista" placeholder="Buscar por título, autor, usuário, lista…" value="${esc(term)}"><button class="btn primary">Buscar</button></form><div class="chips">${[['books','Livros'],['users','Usuários'],['lists','Listas']].map(([v,t])=>`<a class="chip ${type===v?'selected':''}" href="#search?type=${v}&q=${encodeURIComponent(term)}">${t}</a>`).join('')}</div>${results}${type==='books'?`<p><a class="btn" href="#catalog?q=${encodeURIComponent(term)}">Buscar em catálogos externos ou por ISBN</a></p>${!term&&!genre?'<h2>Explorar gêneros</h2><div class="genres">'+genres.map(([g,s])=>`<a class="genre" href="#search?genre=${encodeURIComponent(g)}"><h3>${g}</h3><small>${s}</small></a>`).join('')+'</div>':''}`:''}`;
}
async function catalogPage(){const term=route.params.get('q')||'',isbn=route.params.get('isbn')==='true';let items=[],error='';if(term.length>=2)try{items=await api('/catalog?q='+encodeURIComponent(term)+(isbn?'&isbn=true':''));}catch(e){error=e.message;}state.catalog=items;
 return `${head('Descobrir livros','sua próxima leitura, em português')}<p class="muted catalog-note">Busque pelo título, autor ou ISBN. Priorizamos edições brasileiras; confira a edição e o gênero antes de adicionar.</p><form id="catalog-form" class="form">${field('Título, autor ou ISBN','q','search',term,'required minlength="2" maxlength="150"')}${check('Buscar pela edição exata (ISBN)','isbn',isbn)}<div class="row wrap"><button class="btn primary">Buscar livros</button>${btn('Escanear código','scan-isbn')}</div></form>${error?`<p class="error" role="alert">${esc(error)}</p>`:''}<div class="grid toolbar">${items.map((b,i)=>`<div class="book catalog-book">${cover(b)}<strong>${esc(b.title)}</strong><small>${esc(b.author)}</small><span class="catalog-caption">${esc(b.genre)} · ${b.brazilian?'Edição brasileira':'Português'}</span><small>${esc(b.source)}${b.publisher?' · '+esc(b.publisher):''}</small>${!b.synopsis?'<small>Sinopse não fornecida pelo catálogo</small>':''}${btn('Adicionar ao clube','import-book',i,'btn small')}</div>`).join('')}</div>${term&&!items.length&&!error?empty('Nenhuma edição em português encontrada. Tente outro título ou o ISBN brasileiro.') :''}<p><a href="#create?manual=true">Não encontrou? Cadastrar obra manualmente</a></p>`;
}

function listRow(l){return `<a class="list-row collection-card" href="#list?id=${l.id}"><div class="collection-art ${l.cover_url?'has-cover':''}">${l.cover_url?`<img src="${esc(safeURL(l.cover_url,true))}" alt="Capa da lista ${esc(l.name)}" loading="lazy">`:`<span class="collection-symbol">${icon('lists')}</span><span class="collection-art-label">UMA SELEÇÃO DE HISTÓRIAS</span>`}<span class="collection-privacy">${l.is_public?'Pública':'Privada'}</span></div><div class="collection-copy"><span class="eyebrow">@${esc(l.username||me.username)}</span><h3>${esc(l.name)}</h3><p class="muted">${esc(l.description||'Cada livro, uma razão para estar aqui.')}</p><div class="collection-meta"><span class="collection-visibility">${l.is_public?'Pública':'Privada'}</span><span>${l.book_count} ${Number(l.book_count)===1?'livro':'livros'}</span><span>${icon('heart')} ${l.likes||0}</span><span class="collection-arrow" aria-hidden="true">↗</span></div></div></a>`;}
async function listsPage(){
 const items=await api('/lists'),own=items.filter(l=>String(l.user_id)===String(me.id)),community=items.filter(l=>String(l.user_id)!==String(me.id));
 const filter=route.params.get('filter')||'all',term=route.params.get('q')||'';
 const matches=l=>(l.name+' '+l.description).toLocaleLowerCase('pt-BR').includes(term.toLocaleLowerCase('pt-BR'));
 const shown=own.filter(l=>matches(l)&&(filter==='all'||(filter==='public'?l.is_public:!l.is_public)));
 return `<section class="collections-page"><div class="collections-heading"><div>${head('Listas','curadorias de leitores')}</div>${btn(icon('plus')+' Criar lista','new-list','','btn primary collection-create')}</div><div class="collection-overview"><span class="collection-mark">${icon('lists')}</span><div><strong>${own.length?`${own.length} ${own.length===1?'lista na sua coleção':'listas na sua coleção'}`:'Uma ideia. Muitas histórias.'}</strong><p>${own.length?'Livros que fazem sentido juntos, do seu jeito.':'Reúna os livros que você quer guardar e compartilhar.'}</p></div><a href="#catalog" class="collection-discover">Descobrir livros <span aria-hidden="true">↗</span></a></div><div class="section-heading"><h2>Suas listas</h2><span class="section-count">${own.length.toString().padStart(2,'0')}</span></div>${own.length?`<div class="collection-tools"><nav class="chips" aria-label="Filtrar suas listas">${[['all','Todas'],['public','Públicas'],['private','Privadas']].map(([v,t])=>`<a class="chip ${filter===v?'selected':''}" href="#lists?filter=${v}&q=${encodeURIComponent(term)}">${t}</a>`).join('')}</nav><form id="lists-search" class="collection-search"><label class="sr-only" for="collection-query">Buscar nas suas listas</label><input id="collection-query" name="q" type="search" placeholder="Buscar na sua coleção…" value="${esc(term)}"><button type="submit" class="iconbtn" aria-label="Buscar listas">${icon('search')}</button></form></div><div class="collection-grid">${shown.map(listRow).join('')}</div>${!shown.length?'<p class="muted">Nenhuma lista corresponde a essa busca.</p>':''}`:`<div class="collection-empty"><span class="empty-index" aria-hidden="true">01</span><div><h3>Sua primeira lista começa com uma ideia</h3><p>Favoritos da vida, próximos capítulos ou histórias para dias de chuva. Qual vai ser a sua?</p>${btn('Começar uma coleção '+icon('plus'),'new-list','','textbtn collection-start')}</div></div>`}<div class="section-heading community-heading"><div><h2>Explore listas</h2><p class="muted">Novos caminhos pela estante de outros leitores.</p></div><span class="section-count">${community.length.toString().padStart(2,'0')}</span></div>${community.length?`<div class="collection-grid">${community.map(listRow).join('')}</div>`:`<div class="community-empty"><span>${icon('profile')}</span><p>As próximas descobertas também vêm de outros leitores.<br><small>As listas públicas da comunidade vão aparecer aqui.</small></p></div>`}</section>`;
}
async function listPage(){const l=await api('/lists/'+route.params.get('id')+'?sort='+(route.params.get('sort')||''));state.list=l;const mine=String(l.user_id)===String(me.id);return `${head(l.name,l.is_public?'curadoria pública':'sua lista privada')}<p>${esc(l.description)}</p><div class="toolbar">${mine?btn('Editar lista','edit-list',l.id)+btn('Organizar livros','list-books',l.id)+btn('Excluir','delete-list',l.id,'btn danger'):btn(l.liked?'Descurtir':'Curtir lista','like-list',l.id)}${btn('Copiar link','share-list',l.id)}</div><div class="chips">${[['','Ordem manual'],['rating','Por nota'],['date','Mais recentes']].map(([v,t])=>`<a class="chip ${route.params.get('sort')===v?'selected':''}" href="#list?id=${l.id}&sort=${v}">${t}</a>`).join('')}</div>${books(l.books)}`;}
async function shelfPage(){const items=await api('/shelf'),status=route.params.get('status')||'todos',reading=items.filter(b=>b.status==='lendo');const filtered=items.filter(b=>status==='todos'||b.status===status);return `<section class="shelf-page">${head('Estante','sua biblioteca pessoal')}${reading.length&&(status==='todos'||status==='lendo')?`${sectionTitle('Lendo agora',reading.length+' '+(reading.length===1?'leitura em andamento':'leituras em andamento'),'')}<div class="reading-rail">${reading.map(b=>`<a class="reading-card" href="#book?id=${b.book_id}">${cover(b)}<div><span class="eyebrow">EM ANDAMENTO</span><h2>${esc(b.title)}</h2><p>${esc(b.author)}</p><div class="meter" role="img" aria-label="${Number(b.progress)||0}% concluído"><div style="--pct:${Number(b.progress)||0}%"></div></div><small>${Number(b.progress)||0}% concluído</small></div></a>`).join('')}</div>`:''}<nav class="chips shelf-filters" aria-label="Filtrar estante">${[['todos','Todos'],...Object.entries(statuses)].map(([v,t])=>`<a class="chip ${v===status?'selected':''}" href="#shelf?status=${v}">${t}</a>`).join('')}</nav>${status==='todos'?`${items.filter(b=>b.status==='quero-ler').length?sectionTitle('Quero ler','Próximas escolhas para a sua estante.','')+books(items.filter(b=>b.status==='quero-ler')):''}${sectionTitle('Sua coleção','Todas as histórias que você guardou.','')}${books(items)}`:books(filtered)}<div class="toolbar"><a href="#history">Diário e releituras</a><a href="#quotes">Citações salvas</a></div></section>`;}
async function bookPage(){const id=route.params.get('id');const [b,shelf,reviews,quotes]=await Promise.all([api('/books/'+id),api('/shelf'),api('/reviews?book='+id),api('/quotes')]);state.book=b;state.shelf=shelf.find(s=>String(s.book_id)===String(id));state.reviews=reviews;
 return `<section class="detail">${cover(b)}<div><span class="eyebrow">${esc(b.genre)}</span><h1>${esc(b.title)}</h1><p class="muted">${esc(b.author)}</p>${star(b.rating)}<p class="muted">${esc(b.publisher||'')}${b.publisher?' · ':''}${esc(b.year||'Ano não informado')} · ${b.pages||'—'} páginas${b.isbn?' · ISBN '+esc(b.isbn):''}</p>${!b.verified?'<span class="badge">Cadastro da comunidade · não verificado</span>':''}</div></section><div class="toolbar">${btn(state.shelf?'Atualizar leitura':'Adicionar à estante','shelf-edit',id,'btn primary')}${btn('Escrever resenha','new-review',id)}${btn('Salvar citação','new-quote',id)}${String(b.created_by)===String(me.id)||me.is_admin?btn('Corrigir gênero','genre-edit',id):''}${btn('Denunciar cadastro','report-book',id,'textbtn')}</div>${state.shelf?`<p class="muted">${statuses[state.shelf.status]} · ${state.shelf.progress}%${state.shelf.tags.length?' · '+state.shelf.tags.map(esc).join(', '):''}</p>`:''}<h2>Sobre a obra</h2><p class="synopsis">${esc(b.synopsis||'Sinopse ainda não informada.')}</p><h2>Resenhas do clube</h2><div class="feed">${reviews.map(reviewCard).join('')||empty('Compartilhe a primeira resenha desta obra.')}</div><h2>Suas citações</h2>${quotes.filter(x=>String(x.book_id)===String(id)).map(quoteRow).join('')||'<p class="muted">Guarde os trechos que ficaram com você.</p>'}`;
}
function quoteRow(q){return `<blockquote class="activity"><p>“${esc(q.text)}”</p><small>${esc(q.title)}${q.page?' · p. '+q.page:''}</small><p>${btn('Excluir','delete-quote',q.id,'textbtn')}</p></blockquote>`;}
async function profilePage(){const id=route.params.get('id')||me.id,u=await api('/users/'+id);state.profile=u;const mine=String(me.id)===String(id);const [shelf,reviews,lists]=u.can_view?await Promise.all([api('/shelf?user='+id),api('/reviews?user='+id),api('/lists?user='+id)]):[[],[],[]];state.reviews=reviews;
 return `${u.banner&&u.can_view?`<img class="profile-banner" src="${esc(safeURL(u.banner,true))}" alt="Banner do perfil">`:'<div class="profile-banner"></div>'}<div class="profilehead">${avatar(u)}<div><h1>${esc(u.name)}</h1><a href="#profile?id=${u.id}">@${esc(u.username)}</a>${u.is_private?'<span class="badge">Conta privada</span>':''}</div><div>${mine?btn('Editar perfil','profile-edit'):btn(u.relationship==='following'?'Deixar de seguir':u.relationship==='pending'?'Cancelar solicitação':'Seguir','follow',u.id,'btn primary')}</div></div><p class="bio">${esc(u.bio)}</p><div class="row wrap">${u.links.map(x=>`<a href="${esc(safeURL(x))}" target="_blank" rel="noopener noreferrer">${esc(new URL(x).hostname)}</a>`).join('')}</div><div class="count profile-connections">${btn(u.followers+' seguidores','followers',u.id,'textbtn')}${btn(u.following+' seguindo','following',u.id,'textbtn')}</div>${u.can_view?`<div class="profile-summary"><div><strong>${shelf.length}</strong><span>na estante</span></div><div><strong>${shelf.filter(b=>b.status==='lido').length}</strong><span>lidos</span></div><div><strong>${lists.length}</strong><span>listas</span></div></div>${u.favorites.length?'<h2>Favoritos da vida</h2><div class="favorite">'+books(u.favorites)+'</div>':''}<h2>Estante</h2>${books(shelf)}<h2>Resenhas</h2><div class="feed">${reviews.map(reviewCard).join('')||'<p class="muted">Ainda sem resenhas.</p>'}</div><h2>Listas</h2><div class="profile-lists">${lists.map(listRow).join('')||'<p class="muted">Ainda sem listas.</p>'}</div>`:empty('Este perfil é privado. O leitor precisa aprovar sua solicitação.')}${mine?`<div class="toolbar"><a class="btn" href="#goals">Metas de leitura</a><a class="btn" href="#stats">Estatísticas</a>${me.is_admin?`<a class="btn" href="#moderation">Moderação</a>`:""}${btn('Exportar meus dados','export')}${btn('Sair da conta','logout')}</div>${!me.email_verified?`<div class="notice">Seu e-mail ainda não foi confirmado. ${config.email?btn('Reenviar confirmação','resend','','textbtn'):''}</div>`:''}`:''}`;
}
function goalRow(g){const count=Number(g.completed),target=Number(g.target),pct=Math.min(100,Math.round(count/target*100));const now=new Date(),start=new Date(g.starts_on),end=new Date(g.ends_on);const expected=target*Math.max(0,Math.min(1,(now-start)/(end-start+86400000)));const pace=count>=target?'Meta concluída!':now<start?'Começa em '+date(g.starts_on):now>end?'Período encerrado':count+0.5>=expected?'No prazo ou adiantado':'Um pouco atrás do ritmo';return `<article class="goal"><div class="row spread"><h3>${esc(g.name)}</h3>${btn('Excluir','delete-goal',g.id,'textbtn')}</div><small>${date(g.starts_on)} a ${date(g.ends_on)}</small><p>${count} de ${target} livros · ${pct}%</p><div class="meter"><div style="--pct:${pct}%"></div></div><p class="hint">${pace} ${count>=target?'<span class="badge">Desafio completo</span>':count>=target/2?'<span class="badge">Metade do caminho</span>':''}</p></article>`;}
async function goalsPage(){const goals=await api('/goals');return `${head('Metas','cada livro conta')}<p>Escolha a quantidade e as datas. Leituras concluídas no período atualizam a meta automaticamente.</p>${btn('Criar meta','new-goal','','btn primary')}<div class="goals-grid">${goals.map(goalRow).join('')||empty('Crie uma meta anual, mensal, semanal ou para um período especial.')}</div>`;}
async function statsPage(){const year=new Date().getFullYear(),start=route.params.get('start')||year+'-01-01',end=route.params.get('end')||year+'-12-31';const s=await api('/stats?start='+start+'&end='+end);return `${head('Seu ano em histórias','um retrato das suas leituras')}<form id="stats-form" class="form"><div class="fields">${field('Início','start','date',start,'required')}${field('Fim','end','date',end,'required')}</div><button class="btn">Aplicar período</button></form><div class="stats"><div class="stat panel"><strong>${s.read}</strong>livros concluídos</div><div class="stat panel"><strong>${s.pages}</strong>páginas lidas</div><div class="stat panel"><strong>${s.average||'—'}</strong>média das suas notas (geral)</div></div><div class="chips">${s.achievements.map(x=>`<span class="badge">${x}</span>`).join('')}</div><h2>Gêneros mais lidos</h2>${bars(s.genres)}<h2>Autores mais lidos</h2>${bars(s.authors)}<p class="muted">As páginas representam livros concluídos com número de páginas cadastrado. Releituras contam novamente.</p>${btn('Exportar meus dados em JSON','export')}`;}
function bars(values){const pairs=Object.entries(values).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...pairs.map(x=>x[1]));return pairs.map(([k,n])=>`<div class="bar-row"><span>${esc(k)}</span><div><div class="bar" style="--pct:${Math.round(n/max*100)}%" role="img" aria-label="${esc(k)}: ${n}"></div></div><span>${n}</span></div>`).join('')||'<p class="muted">Conclua uma leitura para ver suas estatísticas.</p>';}
async function notificationsPage(){const [items,requests,goals]=await Promise.all([api('/notifications'),api('/follow-requests'),api('/goals')]);return `${head('Notificações','o que aconteceu no clube')}<div class="toolbar">${btn('Marcar todas como lidas','read-notifications')}</div>${requests.length?'<h2>Solicitações para seguir</h2>'+requests.map(u=>`<div class="notification">${person(u)}<div class="toolbar">${btn('Aprovar','approve-follow',u.id)}${btn('Recusar','reject-follow',u.id)}</div></div>`).join(''):''}${items.map(n=>`<article class="notification ${!n.is_read?'unread':''}"><a href="${n.review_id?'#reviews':'#profile?id='+n.actor_id}">${esc(n.content)}</a><time>${new Date(n.created_at).toLocaleString('pt-BR')}</time></article>`).join('')||empty('Suas interações aparecerão aqui.')}<h2>Lembretes de leitura</h2>${goals.filter(g=>Number(g.completed)<Number(g.target)&&iso(g.ends_on)>=new Date().toISOString().slice(0,10)).map(goalRow).join('')||'<p class="muted">Nenhuma meta em andamento.</p>'}`;}
async function historyPage(){const rows=await api('/history');return `${head('Diário de leitura','histórias concluídas e releituras')}<p class="muted">Para registrar uma releitura, marque o livro como “Lendo” e depois conclua novamente.</p>${rows.map(h=>`<div class="list-row"><a href="#book?id=${h.book_id}"><h3>${esc(h.title)}</h3></a><small>${date(h.started_on)} a ${date(h.finished_on)}</small><p>${btn('Excluir registro do diário','delete-history',h.id,'textbtn')}</p></div>`).join('')||empty('Suas leituras concluídas serão registradas aqui.')}`;}
function createPage(){const b=state.importing||{};return `${head('Novo livro','uma história para o clube')}<p><a class="btn" href="#catalog">Buscar nos catálogos externos</a></p><p class="muted">Cadastros da comunidade recebem o selo “Não verificado”. Confira título, autor e ISBN antes de salvar.</p><form id="book-form" class="form">${field('Título','title','text',b.title||'','required maxlength="300"')}${field('Autor','author','text',b.author||'','required maxlength="300"')}<div class="fields">${field('ISBN-10 ou ISBN-13 (opcional)','isbn','text',b.isbn||'','maxlength="30"')}${field('Páginas','pages','number',b.pages||'','min="1" max="100000"')}</div><div class="fields">${select('Gênero','genre',(config.genres||['Geral']).map(g=>[g,g]),b.genre||'Geral')}${field('Ano/edição','year','text',b.year||'','maxlength="20"')}</div>${field('Editora','publisher','text',b.publisher||'','maxlength="300"')}${field('URL HTTPS da capa','cover_url','url',b.cover_url||'')}${field('Ou enviar capa (PNG, JPEG ou WebP até 1 MB)','cover_file','file','','accept="image/png,image/jpeg,image/webp"')}${area('Sinopse','synopsis',b.synopsis||'','maxlength="12000"')}${submit('Salvar no catálogo')}</form>`;}
async function moderationPage(){const data=await api('/moderation');return head('Moderação','revisão dos cadastros da comunidade')+'<h2>Livros não verificados</h2>'+data.books.map(b=>`<div class="list-row"><a href="#book?id=${b.id}"><h3>${esc(b.title)}</h3></a><p>${esc(b.author)} · ISBN ${esc(b.isbn||'não informado')}</p>${btn('Verificar cadastro','verify-book',b.id)}</div>`).join('')+'<h2>Denúncias pendentes</h2>'+data.reports.map(r=>`<div class="list-row"><h3>${esc(r.title)}</h3><p>${esc(r.reason)}</p>${btn('Marcar como revisada','resolve-report',r.id)}</div>`).join('');}
const pages={home,discovery:discoveryPage,search:searchPage,catalog:catalogPage,reviews:reviewsPage,lists:listsPage,list:listPage,shelf:shelfPage,book:bookPage,profile:profilePage,goals:goalsPage,stats:statsPage,notifications:notificationsPage,history:historyPage,create:createPage,moderation:moderationPage,quotes:async()=>head('Citações','palavras que ficaram')+(await api('/quotes')).map(quoteRow).join('')};
async function navigate(){const current=++generation;route=parseRoute();closeDialog();window.scrollTo(0,0);if(route.name==='verify'){try{await send('/auth/verify',{token:route.params.get('token')});toast('E-mail confirmado!');if(me)me=await api('/auth/me');location.hash=me?'profile':'login';}catch(e){mount(`<main class="auth"><div>${head('Link de confirmação',e.message)}<a href="#login">Voltar</a></div></main>`);}return;}
 if(!me){authPage(['register','forgot','reset'].includes(route.name)?route.name:'login');return;}if(['login','register'].includes(route.name)){location.hash='home';return;}if(route.name==='reset'){authPage('reset');return;}
 mount('<p class="loading">Abrindo sua próxima história…</p>');try{const html=await(pages[route.name]||pages.home)();if(current!==generation)return;mount(html);bindPage();updateUnread();}catch(e){if(current===generation)mount(head('Não foi possível abrir esta página',e.message)+'<a class="btn" href="#home">Voltar ao início</a>');}
}
function bindPage(){form('#lists-search',v=>{location.hash='lists?filter='+(route.params.get('filter')||'all')+'&q='+encodeURIComponent(v.q);});form('#search-form',v=>{location.hash='search?type='+(route.params.get('type')||'books')+'&q='+encodeURIComponent(v.q);});form('#catalog-form',(v,f)=>{location.hash='catalog?q='+encodeURIComponent(v.q)+'&isbn='+f.elements.isbn.checked;});form('#book-form',async(v,f)=>{const file=f.elements.cover_file.files[0];if(file)v.cover_url=await readImage(file);delete v.cover_file;const r=await send('/books',v);state.importing=null;toast(r.existing?'Este livro já estava no clube.':'Livro cadastrado.');location.hash='book?id='+r.id;});form('#stats-form',v=>{location.hash='stats?start='+v.start+'&end='+v.end;});}
async function refresh(){await navigate();}
const actions={
 'retry-discovery':async()=>loadDiscovery(),
 'save-discovery':async()=>{const d=state.discovery;if(!d?.book)return;const b=d.book;const saved=b.id?b:await send('/books',b);const shelf=await api('/shelf');if(!shelf.some(x=>String(x.book_id)===String(saved.id)))await send('/shelf/'+saved.id,{status:'quero-ler'},'PUT');toast('Livro guardado na sua estante.');location.hash='book?id='+saved.id;},
 password:(id,el)=>{const input=el.closest('.password').querySelector('input');input.type=input.type==='password'?'text':'password';el.setAttribute('aria-label',input.type==='password'?'Mostrar senha':'Ocultar senha');},
 logout:async()=>{await send('/auth/logout');me=null;stream?.close();stream=null;location.hash='login';await navigate();},
 'import-book':async id=>{const b={...state.catalog[Number(id)]};if(b.isbn)try{const extra=await api('/catalog/details?isbn='+encodeURIComponent(b.isbn));if(extra.isbn===b.isbn)for(const key of ['title','author','publisher','genre','year','pages','synopsis','cover_url'])if(extra[key])b[key]=extra[key];}catch{toast('Usando os dados encontrados. Você pode completar a edição antes de salvar.');}state.importing=b;location.hash='create?manual=true';},
 'genre-edit':async id=>{dialog(`<h2>Corrigir gênero</h2><form id="genre-form" class="form">${select('Gênero','genre',config.genres.map(g=>[g,g]),state.book.genre)}${submit('Salvar gênero')}</form>`);form('#genre-form',async v=>{await send('/books/'+id+'/genre',v,'PUT');closeDialog();toast('Gênero corrigido.');await refresh();});},
 'profile-edit':async()=>{const [fresh,catalog]=await Promise.all([api('/auth/me'),api('/books')]);me=fresh;const nextChange=me.username_change_available_at?new Date(me.username_change_available_at):null;const locked=nextChange&&nextChange>new Date();dialog(`<h2>Seu perfil</h2><form id="profile-form" class="form">${field('Nome de exibição','name','text',me.name,'required maxlength="120"')}${field('Nome de usuário (@)','username','text',me.username,`required minlength="3" maxlength="40" pattern="[a-zA-Z0-9][a-zA-Z0-9_.-]{2,39}" autocapitalize="none" spellcheck="false" aria-describedby="username-help" ${locked?'readonly':''}`)}<small id="username-help" class="username-help">${locked?'Você poderá trocar seu @ novamente em '+esc(nextChange.toLocaleString('pt-BR'))+'. Você pode editar os outros dados normalmente.':'Escolha um @ único, com 3 a 40 caracteres. Use letras sem acento, números, ponto, hífen ou sublinhado. Após a troca, aguarde 10 dias para mudar novamente. Seu @ anterior ficará disponível para outras pessoas.'}</small>${area('Bio','bio',me.bio||'','maxlength="1000"')}${field('Avatar (PNG, JPEG ou WebP até 1 MB)','avatar_file','file','','accept="image/png,image/jpeg,image/webp"')}${field('Banner (PNG, JPEG ou WebP até 1 MB)','banner_file','file','','accept="image/png,image/jpeg,image/webp"')}${area('Links externos (um HTTPS por linha, até cinco)','links',(me.links||[]).join('\n'))}<fieldset><legend>Seus quatro favoritos da vida</legend><div class="checkbooks">${catalog.map(b=>`<label><input type="checkbox" name="favorites" value="${b.id}" ${(me.favorites||[]).map(String).includes(String(b.id))?'checked':''}>${esc(b.title)}</label>`).join('')}</div></fieldset>${check('Conta privada: aprovar seguidores e proteger estante e resenhas','is_private',me.is_private)}${submit()}</form>`);form('#profile-form',async(v,f)=>{const favorites=[...new FormData(f).getAll('favorites')].map(Number);if(favorites.length>4)throw Error('Escolha até quatro favoritos.');const values={name:v.name,username:v.username,bio:v.bio,links:v.links.split('\n').map(x=>x.trim()).filter(Boolean),is_private:f.elements.is_private.checked,favorites};for(const name of ['avatar','banner']){const file=f.elements[name+'_file'].files[0];if(file)values[name]=await readImage(file);}me=await send('/profile',values,'PUT');closeDialog();toast('Perfil atualizado.');await refresh();});},
 follow:async()=>{await send('/users/'+state.profile.id+'/follow',{follow:state.profile.relationship==='none'},'PUT');await refresh();},
 followers:id=>showPeople('/users/'+id+'/followers','Seguidores'),following:id=>showPeople('/users/'+id+'/following','Seguindo'),
 'approve-follow':async id=>{await send('/follow-requests/'+id,{approve:true},'PUT');await refresh();},'reject-follow':async id=>{await send('/follow-requests/'+id,{approve:false},'PUT');await refresh();},
 'shelf-edit':()=>{const s=state.shelf||{},b=state.book;dialog(`<h2>Sua leitura</h2><p>${esc(b.title)}</p><form id="shelf-form" class="form">${select('Estado de leitura','status',Object.entries(statuses),s.status||'quero-ler')}${field('Página atual','current_page','number',s.current_page||0,`min="0" ${b.pages?'max="'+b.pages+'"':''}`)}${!b.pages?field('Progresso (%)','progress','number',s.progress||0,'min="0" max="100"'):''}<div class="fields">${field('Início (opcional)','started_on','date',iso(s.started_on))}${field('Conclusão (para livro lido)','finished_on','date',iso(s.finished_on))}</div>${field('Etiquetas separadas por vírgula','tags','text',(s.tags||[]).join(', '))}${submit('Salvar leitura')}${s.book_id?btn('Remover da estante','remove-shelf',b.id,'btn danger'):''}</form>`);form('#shelf-form',async v=>{await send('/shelf/'+b.id,{...v,tags:v.tags.split(',').map(x=>x.trim()).filter(Boolean)},'PUT');closeDialog();toast('Leitura atualizada.');await refresh();});},
 'remove-shelf':id=>confirmAction('Remover este livro da estante? O diário continua salvo.',async()=>{await api('/shelf/'+id,{method:'DELETE'});closeDialog();await refresh();}),
 'new-review':()=>editReview(state.book.id,state.reviews.find(r=>String(r.user_id)===String(me.id))),
 'edit-review':id=>{const r=state.reviews.find(r=>String(r.id)===String(id));editReview(r.book_id,r);},
 'delete-review':id=>confirmAction('Excluir esta resenha, curtidas e comentários?',async()=>{await api('/reviews/'+id,{method:'DELETE'});closeDialog();await refresh();}),
 'like-review':async(id,el)=>{const r=state.reviews.find(x=>String(x.id)===String(id));await send('/reviews/'+id+'/like',{liked:!r.liked},'PUT');r.likes+=r.liked?-1:1;r.liked=!r.liked;el.innerHTML=icon('heart')+' '+r.likes;el.classList.toggle('liked',r.liked);},
 comments:async id=>{const items=await api('/reviews/'+id+'/comments');dialog(`<h2>Conversa sobre a resenha</h2>${items.map(c=>`<article class="comment">${person({...c,user_id:c.user_id})}<p>${esc(c.content)}</p>${String(c.user_id)===String(me.id)?btn('Excluir','delete-comment',c.id,'textbtn'):''}</article>`).join('')||'<p class="muted">Comece a conversa.</p>'}<form id="comment-form" class="form">${area('Seu comentário','content','','required maxlength="2000"')}${submit('Comentar')}</form>`);form('#comment-form',async v=>{await send('/reviews/'+id+'/comments',v);await actions.comments(id);});},
 'delete-comment':async id=>{await api('/comments/'+id,{method:'DELETE'});closeDialog();toast('Comentário excluído.');await refresh();},
 'more-reviews':async(id,el)=>{state.reviewOffset+=30;const more=await api('/reviews?following='+(route.params.get('following')==='true')+'&offset='+state.reviewOffset);state.reviews.push(...more);$('#feed').insertAdjacentHTML('beforeend',more.map(reviewCard).join(''));wireImages();if(more.length<30)el.remove();},
 'new-list':()=>listEditor(), 'edit-list':()=>listEditor(state.list),
 'delete-list':id=>confirmAction('Excluir esta lista?',async()=>{await api('/lists/'+id,{method:'DELETE'});closeDialog();location.hash='lists';}),
 'like-list':async id=>{await send('/lists/'+id+'/like',{liked:!state.list.liked},'PUT');await refresh();},
 'share-list':async id=>{const url=new URL(location.href);url.hash='list?id='+id;await navigator.clipboard.writeText(url.href);toast('Link copiado. Listas privadas só podem ser vistas por você.');},
 'list-books':async id=>{const catalog=await api('/books');const l=state.list;state.order=l.books.map(b=>String(b.id));state.allBooks=[...new Map([...l.books,...catalog].map(b=>[String(b.id),b])).values()];dialog(`<h2>Livros da lista</h2><p class="muted">Arraste para ordenar ou use os botões de subir e descer.</p><div id="ordered-books"></div><h3>Adicionar livros</h3><div class="checkbooks">${state.allBooks.map(b=>`<label><input type="checkbox" data-list-book="${b.id}" ${state.order.includes(String(b.id))?'checked':''}>${esc(b.title)}</label>`).join('')}</div><p>${btn('Salvar organização','save-order',id,'btn primary')}</p>`);drawOrder();},
 'order-up':id=>moveOrder(id,-1),'order-down':id=>moveOrder(id,1),
 'save-order':async id=>{await send('/lists/'+id+'/books',{book_ids:state.order.map(Number)},'PUT');closeDialog();toast('Lista atualizada.');await refresh();},
 'new-goal':()=>{dialog(`<h2>Uma nova meta</h2><form id="goal-form" class="form">${field('Nome da meta','name','text','','required maxlength="120"')}${field('Quantidade de livros','target','number',12,'min="1" max="10000" required')}${select('Período','period',[['year','Este ano'],['month','Este mês'],['week','Esta semana'],['custom','Personalizado']],'year')}<div class="fields">${field('Data inicial','starts_on','date',new Date().getFullYear()+'-01-01','required')}${field('Data final','ends_on','date',new Date().getFullYear()+'-12-31','required')}</div>${submit('Criar meta')}</form>`);$('#goal-form [name=period]').addEventListener('change',e=>{const now=new Date(),start=new Date(now),end=new Date(now),type=e.target.value;if(type==='custom')return;if(type==='year'){start.setMonth(0,1);end.setMonth(11,31);}if(type==='month'){start.setDate(1);end.setMonth(end.getMonth()+1,0);}if(type==='week'){const day=(start.getDay()+6)%7;start.setDate(start.getDate()-day);end.setDate(start.getDate()+6);}$('#goal-form [name=starts_on]').value=localISO(start);$('#goal-form [name=ends_on]').value=localISO(end);});form('#goal-form',async v=>{await send('/goals',v);closeDialog();await refresh();});},
 'delete-goal':id=>confirmAction('Excluir esta meta? Seu histórico de leitura permanece salvo.',async()=>{await api('/goals/'+id,{method:'DELETE'});closeDialog();await refresh();}),
 'new-quote':()=>{dialog(`<h2>Um trecho para guardar</h2><form id="quote-form" class="form">${area('Citação','text','','required maxlength="5000"')}${field('Página (opcional)','page','number','','min="1"')}${submit('Guardar citação')}</form>`);form('#quote-form',async v=>{await send('/quotes',{...v,book_id:state.book.id});closeDialog();await refresh();});},
 'delete-quote':id=>confirmAction('Excluir esta citação?',async()=>{await api('/quotes/'+id,{method:'DELETE'});closeDialog();await refresh();}),
 'delete-history':id=>confirmAction('Excluir esta conclusão do diário? Isso também atualiza as metas.',async()=>{await api('/history/'+id,{method:'DELETE'});closeDialog();await refresh();}),
 'report-book':()=>{dialog(`<h2>Denunciar cadastro</h2><form id="report-form" class="form">${area('Descreva o problema (spam, obra duplicada ou dados incorretos)','reason','','required minlength="5" maxlength="1000"')}${submit('Enviar denúncia')}</form>`);form('#report-form',async v=>{await send('/books/'+state.book.id+'/report',v);closeDialog();toast('Denúncia registrada para revisão.');});},
 'read-notifications':async()=>{await send('/notifications/read',{},'PUT');await refresh();},
 resend:async()=>{await send('/auth/resend');toast('Confira o link de confirmação no seu e-mail.');},
 export:async()=>{const data=await api('/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bookclub-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
 'scan-isbn':async()=>{if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){toast('Leitura por câmera indisponível neste navegador. Digite o ISBN.');return;}dialog('<h2>Escanear ISBN</h2><p>Aponte a câmera para o código de barras do livro.</p><video class="scanner" autoplay playsinline muted></video><p class="muted">A câmera será desligada ao fechar esta janela.</p>');const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=$('#modal video');video.srcObject=media;await video.play();const detector=new BarcodeDetector({formats:['ean_13','ean_8']});let active=true;scanStop=()=>{active=false;media.getTracks().forEach(t=>t.stop());};const scan=async()=>{if(!active)return;try{const codes=await detector.detect(video);const code=codes.find(c=>c.rawValue.length===13);if(code){closeDialog();location.hash='catalog?isbn=true&q='+encodeURIComponent(code.rawValue);return;}}catch{}if(active)setTimeout(scan,500);};scan();}
};
function localISO(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function confirmAction(message,handler){dialog(`<h2>Confirmar alteração</h2><p>${esc(message)}</p><div class="toolbar">${btn('Confirmar','confirm','','btn primary')}${btn('Cancelar','cancel')}</div>`);state.confirm=handler;}
actions.confirm=()=>state.confirm?.();actions.cancel=closeDialog;
actions['verify-book']=async id=>{await send('/moderation/books/'+id,{verified:true},'PUT');await refresh();};
actions['resolve-report']=async id=>{await send('/moderation/reports/'+id,{},'PUT');await refresh();};
async function showPeople(path,title){const users=await api(path);dialog(`<h2>${title}</h2>${users.map(u=>`<div class="list-row">${person(u)}</div>`).join('')||'<p class="muted">Ninguém por aqui ainda.</p>'}`);}
function editReview(bookId,r={}){dialog(`<h2>Sua resenha</h2><form id="review-form" class="form">${select('Sua nota','rating',Array.from({length:10},(_,i)=>[(i+1)/2,((i+1)/2).toLocaleString('pt-BR')+' estrela(s)']),r.rating||5)}${area('O que você achou?','content',r.content||'','required maxlength="15000"')}${check('Esta resenha contém spoilers','spoiler',r.spoiler)}${submit('Publicar resenha')}</form>`);form('#review-form',async(v,f)=>{await send('/reviews',{book_id:bookId,rating:Number(v.rating),content:v.content,spoiler:f.elements.spoiler.checked});closeDialog();toast('Resenha publicada.');await refresh();});}
function listEditor(l={}){dialog(`<h2>${l.id?'Editar':'Criar'} lista</h2><form id="list-form" class="form">${field('Título','name','text',l.name||'','required maxlength="120"')}${area('Descrição','description',l.description||'','maxlength="2000"')}${field('Capa própria (PNG, JPEG ou WebP até 1 MB)','cover_file','file','','accept="image/png,image/jpeg,image/webp"')}${check('Lista pública','is_public',l.is_public!==false)}${submit()}</form>`);form('#list-form',async(v,f)=>{const values={name:v.name,description:v.description,is_public:f.elements.is_public.checked,cover_url:l.cover_url||''};if(f.elements.cover_file.files[0])values.cover_url=await readImage(f.elements.cover_file.files[0]);const result=await send('/lists'+(l.id?'/'+l.id:''),values,l.id?'PUT':'POST');closeDialog();if(location.hash==='#list?id='+result.id)await refresh();else location.hash='list?id='+result.id;});}
async function readImage(file){if(file.size>1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Use imagem PNG, JPEG ou WebP de até 1 MB.');const raw=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=()=>reject(Error('Não foi possível ler a imagem.'));fr.readAsDataURL(file);});const image=new Image();image.src=raw;await image.decode();if(image.width>6000||image.height>6000)throw Error('A imagem excede 6000 pixels.');return raw;}
function drawOrder(){const holder=$('#ordered-books');if(!holder)return;holder.innerHTML=state.order.map(id=>{const b=state.allBooks.find(x=>String(x.id)===id);return `<div class="dragrow" draggable="true" data-book="${id}">${cover(b)}<strong>${esc(b.title)}</strong>${btn('↑','order-up',id,'btn small')}${btn('↓','order-down',id,'btn small')}</div>`;}).join('');holder.querySelectorAll('.dragrow').forEach(el=>{el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',el.dataset.book));el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('drop',e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(!state.order.includes(id))return;const target=state.order.indexOf(el.dataset.book);state.order=state.order.filter(x=>x!==id);state.order.splice(target,0,id);drawOrder();});});}
function moveOrder(id,delta){const index=state.order.indexOf(String(id)),to=index+delta;if(to>=0&&to<state.order.length){[state.order[index],state.order[to]]=[state.order[to],state.order[index]];drawOrder();}}
document.addEventListener('change',e=>{const id=e.target.dataset.listBook;if(id){if(e.target.checked&&!state.order.includes(id))state.order.push(id);else if(!e.target.checked)state.order=state.order.filter(x=>x!==id);drawOrder();}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=actions[el.dataset.action];if(!action)return;el.disabled=true;try{await action(el.dataset.id,el);}catch(err){toast(err.message);}finally{el.disabled=false;}});
async function updateUnread(){if(!me)return;try{const items=await api('/notifications');$('#unread-dot')?.classList.toggle('hidden',!items.some(n=>!n.is_read));}catch{}}
async function updateHomeLive(){
 if(route.name!=='home'||$('#modal').open)return;
 const current=generation;
 try{const [reviews,activities]=await Promise.all([api('/reviews?following=true'),api('/activities')]);
 if(current!==generation||route.name!=='home'||$('#modal').open)return;
 state.reviews=reviews;
 if($('#home-reviews'))$('#home-reviews').innerHTML=reviews.slice(0,4).map(reviewCard).join('')||empty('Siga leitores para acompanhar as resenhas deles.');
 if($('#home-activities'))$('#home-activities').innerHTML=activities.map(a=>`<div class="activity"><a href="#profile?id=${a.user_id}">@${esc(a.username)}</a><p>${esc(a.content)}</p><small>${date(a.created_at)}</small></div>`).join('')||'<p class="muted">As movimentações da sua comunidade aparecerão aqui.</p>';
 wireImages();}catch{}
}
function connectStream(){stream?.close();stream=new EventSource('/api/events');stream.addEventListener('change',()=>{clearTimeout(state.liveTimer);state.liveTimer=setTimeout(async()=>{await updateUnread();if($('#modal').open)return;if(route.name==='notifications')navigate();if(route.name==='home')updateHomeLive();if(route.name==='reviews'&&state.reviewOffset===0){try{const items=await api('/reviews?following='+(route.params.get('following')==='true'));if(route.name!=='reviews'||$('#modal').open)return;state.reviews=items;const feed=$('#feed');if(feed){feed.innerHTML=items.map(reviewCard).join('')||empty('Nenhuma resenha por aqui ainda.');wireImages();}}catch{}}},600);});}
window.addEventListener('hashchange',navigate);
window.addEventListener('online',()=>toast('Conexão restabelecida.'));
window.addEventListener('offline',()=>toast('Sem conexão. Aguarde antes de salvar alterações.'));
(async()=>{try{config=await api('/config');try{me=await api('/auth/me');}catch{me=null;}if(me)connectStream();await navigate();}catch(e){mount(`<main class="auth"><div>${head('O clube está temporariamente indisponível',e.message)}<p>Confira se o servidor está em execução.</p><a class="btn" href="/">Tentar novamente</a></div></main>`);}})();

// Atualiza a descoberta quando um dia vira com a página aberta, sem agendamento externo.
setInterval(()=>{if(me&&route.name==='home'&&!document.hidden&&state.discovery){const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo'}).format(new Date());if(today!==state.discovery.date)loadDiscovery();}},60000);
